{"code": "export async function main(input: { project: string }) {
  const { issues } = await sdk.sentry.listIssues({ project: input.project });
  const unresolved = issues.filter(i => i.status === "unresolved" && i.count >= 0);
  const culprits = [...new Set(unresolved.map(i => i.culprit))].sort();

  const out: any[] = [];
  for (const c of culprits) {
    const { issues: found } = await sdk.linear.searchIssues({ query: c });
    out.push({
      culprit: c,
      sentryIssues: unresolved.filter(i => i.culprit === c).map(i => i.shortId),
      found: found.map(f => ({ identifier: f.identifier, title: f.title, description: f.description, state: f.state })),
    });
  }
  return out;
}", "input": {"project": "jobs"}}

{"code": "export async function main(input: { project: string }) {
  const { issues } = await sdk.sentry.listIssues({ project: input.project });
  const unresolved = issues.filter(i => i.status === "unresolved");
  const culprits = [...new Set(unresolved.map(i => i.culprit))].sort();

  const queries = new Set<string>();
  for (const c of culprits) {
    queries.add(c);
    for (const part of c.split(" ")) queries.add(part);
  }
  queries.add("Sentry");

  const results: any = {};
  for (const q of [...queries].sort()) {
    const { issues: found } = await sdk.linear.searchIssues({ query: q });
    results[q] = found.map(f => ({ identifier: f.identifier, title: f.title, description: f.description, state: f.state }));
  }
  return results;
}", "input": {"project": "jobs"}}

{"code": "export async function main(input: { project: string }) {
  const { issues } = await sdk.sentry.listIssues({ project: input.project });
  const unresolved = issues.filter(i => i.status === "unresolved" && i.count >= 0);
  const culprits = [...new Set(unresolved.map(i => i.culprit))].sort();

  const plan: any[] = [];
  for (const c of culprits) {
    const { issues: found } = await sdk.linear.searchIssues({ query: c });
    const already = found.some(f =>
      f.title.includes(c) || f.description.includes(c)
    );
    if (already) {
      plan.push({ culprit: c, action: "skipped-existing", matches: found.map(f => f.identifier) });
      continue;
    }
    const created = await sdk.linear.createIssue({ title: `[Sentry] ${c}`, description: c });
    plan.push({
      culprit: c,
      action: "created",
      sentryIssues: unresolved.filter(i => i.culprit === c).map(i => i.shortId),
      created,
    });
  }
  return plan;
}", "input": {"project": "jobs"}}

